import React from 'react';
import { Link, Routes, Route } from 'react-router-dom';
import Home from '../pages/Home';
import Projects from '../pages/Projects';
import Contacts from '../pages/Contacts';

const Layout = () => {
  return (
    <div style={{ position: "relative", minHeight: "100vh", fontFamily: "sans-serif" }}>
      
      {/* Верхнее меню справа */}
      <div style={{
        position: "absolute",
        top: "20px",
        right: "20px",
        display: "flex",
        gap: "15px"
      }}>
        <Link to="/" style={menuBtnStyle}>Home</Link>
        <Link to="/projects" style={menuBtnStyle}>Projects</Link>
        <Link to="/contacts" style={menuBtnStyle}>Contacts</Link>
      </div>

      {/* Основной контент */}
      <div style={{ paddingTop: "80px" }}>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/projects" element={<Projects />} />
          <Route path="/contacts" element={<Contacts />} />
        </Routes>
      </div>
    </div>
  );
};

// Стили кнопок меню
const menuBtnStyle = {
  padding: "8px 16px",
  backgroundColor: "#4CAF50",
  color: "white",
  textDecoration: "none",
  borderRadius: "5px",
  fontWeight: "bold",
  cursor: "pointer"
};

export default Layout;
